import java.util.HashMap;
import java.util.Map;
import java.util.Scanner;

public class Main {
    static Map<Long, Long> memo = new HashMap<>();

    static int countDigits(long x) {
        int cnt = 0;
        while (x != 0) {
            cnt++;
            x /= 10;
        }
        return cnt;
    }

    static long reverseNum(long x) {
        long[] arr = new long[17];
        int p = 0;
        while (x != 0) {
            arr[p++] = (x % 10) - (x < 0 ? -1 : 1);
            x /= 10;
        }
        long res = 0;
        while (p-- > 0) {
            res = res * 10 + arr[p];
        }
        return res;
    }

    static long prevValue(long x) {
        long c = 0, orig = x;
        while (x != 0) {
            c *= 10;
            c += (x < 0 ? -1 : 1);
            x /= 10;
        }
        c *= 10;
        c++;
        return orig - c;
    }

    static long getLast(long x) {
        while (x >= 10) {
            x /= 10;
        }
        return x;
    }

    static long removeLeading(long x) {
        long[] arr = new long[17];
        int p = 0;
        while (x >= 10) {
            arr[p++] = x % 10;
            x /= 10;
        }
        long res = 0;
        while (p-- > 0) {
            res = res * 10 + arr[p];
        }
        return res;
    }

    static long solve(long x) {
        if (x <= 11) {
            return Math.min(13 - x, x);
        }
        if (memo.containsKey(x))
            return memo.get(x);
        int n = 0;
        long t = 1;
        while (t < x) {
            t = t * 10 + 1;
            n++;
        }
        if (x * 2 >= t) {
            long res = Math.min(solve(t - x) + n + 1, (x / (t / 10)) * n + solve(x % (t / 10)));
            memo.put(x, res);
            return res;
        }
        long res = (x / (t / 10)) * n + solve(x % (t / 10));
        memo.put(x, res);
        return res;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long a = sc.nextLong();
        System.out.println(solve(a));
        sc.close();
    }
}
